import {chromium} from '@playwright/test';
import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const stage='.local/step07/fix-round4/final',record=JSON.parse(await readFile(stage+'/browser-production/evidence.json','utf8')),browser=await chromium.launch(),page=await browser.newPage({viewport:{width:1200,height:900}}),errors=[],consoleErrors=[],responses=[];
page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')consoleErrors.push(m.text());});page.on('response',r=>responses.push({url:r.url(),status:r.status()}));
await page.goto('http://127.0.0.1:4376');await page.evaluate(id=>localStorage.setItem('studio-project',id),record.projectId);await page.reload();await page.getByText('画布已就绪 · 实际导出图集',{exact:false}).waitFor({timeout:30000});
const canvas=page.locator('canvas[aria-label="交付拼接预览"]');if(await canvas.getAttribute('data-build-id')!==record.retired)throw Error('retained actual current mismatch');
const png=page.getByAltText('当前配方处理水面');await png.waitFor({timeout:60000});await page.waitForFunction(()=>{const i=document.querySelector('img[alt="当前配方处理水面"]');return i?.complete&&i.naturalWidth===96&&i.naturalHeight===144;});
const image=await png.evaluate(i=>({project:i.dataset.projectId,recipe:i.dataset.recipeId,frame:Number(i.dataset.sourceFrame),pngSha:i.dataset.pngSha256,width:i.naturalWidth,height:i.naturalHeight}));if(image.project!==record.projectId)throw Error('retained processed project mismatch');
const r=await page.request.get(`http://127.0.0.1:4376/api/projects/${record.projectId}/recipes/${image.recipe}/processed?frame=${image.frame}`);if(r.status()!==200||createHash('sha256').update(await r.body()).digest('hex')!==image.pngSha)throw Error('retained actual processed PNG mismatch');
await page.screenshot({path:stage+'/retained-runtime.png',fullPage:true});await browser.close();if(errors.length||consoleErrors.length||responses.some(r=>r.status>=400))throw Error('retained entry browser error');
await writeFile(stage+'/retained-entry-browser.json',JSON.stringify({sourceSHA:record.sourceCommit,project:record.projectId,currentBuild:record.retired,processedImage:image,errors,consoleErrors,responses,entry:'http://127.0.0.1:4376'},null,2)+'\n');console.log('OWNED_PRODUCTION_ENTRY_ACTUAL_CANVAS_PROCESSED_PASS');
